pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1 ether);
        vm.assume(actor != address(c));

        // fund the actor and have it deposit into c via fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        address(c).call{value: amount}("");
        require(address(c).balance == amount, "deposit failed");

        uint256 ownerBefore = address(this).balance;

        // owner (the deployer == this contract) withdraws everything
        c.withdrawAll();

        // Rule: owner receives exactly the contract balance; buggy version sends nothing.
        assertTrue(address(this).balance == ownerBefore + amount && address(c).balance == 0);
    }
}

