pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract with a fuzzed amount via its fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertTrue(address(c).balance == amount);

        // owner calls withdrawAll; it must not revert and must drain the balance
        vm.prank(c.owner());
        c.withdrawAll();

        // GENERAL RULE: after withdrawAll(), the contract retains NO ether (balance == 0).
        // The mutant withdraws 0, leaving the full fuzzed amount in the contract.
        assertTrue(address(c).balance == 0);
    }
}

