pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: the caller is not the owner (deployer = this test contract)
        vm.assume(actor != address(this) && actor != address(c) && actor != address(0));
        vm.deal(actor, amount);

        // 1st rejected call: warms c's account and the owner storage slot for BOTH versions
        vm.prank(actor);
        try c.withdrawAll() { } catch { }

        // 2nd rejected call, measured in fully warm state:
        // in P the revert is raised immediately at the entry guard of withdrawAll,
        // so the gas burned is a small constant;
        // in M the body runs and performs an extra nested self-call (frame setup,
        // ABI decode of _value, second guard evaluation) before reverting,
        // measurably exceeding that constant.
        uint256 g0 = gasleft();
        vm.prank(actor);
        try c.withdrawAll() { } catch { }
        uint256 used = g0 - gasleft();

        assertTrue(used < 1100, "non-owner withdrawAll must be rejected at the entry guard itself");
    }
}

