pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0); // plain EOA recipient, transfer always succeeds if reached
        amount = bound(amount, 1, type(uint256).max / 2);

        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: a non-owner's withdrawAll is rejected at the guard, so the call reverts
        // and c's balance is untouched. The mutant pays out and empties the balance.
        assertTrue(!ok && address(c).balance == balBefore && address(c).balance > 0);
    }
}

